/** Pure operations over the in-memory todo list. The CLI and the store are
  * the only things that touch `IO`; this takes and returns values.
  */
object TodoOps:

  def add(todos: List[Todo], rawTitle: String): Either[String, (List[Todo], Todo)] =
    Title(rawTitle).map { title =>
      val todo = Todo(nextId(todos), title, done = false)
      (todos :+ todo, todo)
    }

  private def nextId(todos: List[Todo]): Int =
    todos.map(_.id).maxOption.getOrElse(0) + 1

