package todo

import cats.effect.IO
import java.nio.file.{Files, Path}
import org.virtuslab.yaml.*

/** The YAML-backed store. Read and write both take the file path
  * explicitly - no hardcoded global path - so tests exercise a real temp
  * file with no mocking.
  */
object Store:

  private final case class Record(id: Int, title: String, done: Boolean) derives YamlCodec

  def read(path: Path): IO[Either[String, List[Todo]]] =
    IO.blocking(Files.exists(path)).flatMap { exists =>
      if !exists then IO.pure(Right(List.empty))
      else IO.blocking(Files.readString(path)).map(decode)
    }

  def write(path: Path, todos: List[Todo]): IO[Unit] =
    IO.blocking {
      val records = todos.map(t => Record(t.id, t.title.value, t.done))
      Option(path.getParent).foreach(Files.createDirectories(_))
      Files.writeString(path, records.asYaml)
    }

  private def decode(raw: String): Either[String, List[Todo]] =
    raw.as[List[Record]] match
      case Left(err)      => Left(s"malformed store: ${err.msg}")
      case Right(records) => toTodos(records)

  private def toTodos(records: List[Record]): Either[String, List[Todo]] =
    records.foldLeft[Either[String, List[Todo]]](Right(List.empty)) { (acc, record) =>
      for
        todos <- acc
        todo  <- Todo.create(record.id, record.title, record.done)
      yield todos :+ todo
    }

