package todo

import cats.effect.{ExitCode, IO}
import java.nio.file.Path

/** What a CLI invocation resolved to: the text to print and the exit code
  * the process should use. Handlers resolve to this instead of printing
  * directly, so tests assert on it without capturing real stdout.
  */
final case class CliResult(output: String, exitCode: ExitCode)

/** CLI command handlers. Each wires a store read/write to the pure
  * `TodoOps`; no domain logic lives here.
  */
object Commands:

  def add(path: Path, rawTitle: String): IO[CliResult] =
    Store.read(path).flatMap {
      case Left(err) => IO.pure(CliResult(err, ExitCode.Error))
      case Right(todos) =>
        TodoOps.add(todos, rawTitle) match
          case Left(err) => IO.pure(CliResult(err, ExitCode.Error))
          case Right((updated, added)) =>
            Store
              .write(path, updated)
              .as(CliResult(s"added #${added.id}: ${added.title.value}", ExitCode.Success))
    }

  def list(path: Path): IO[CliResult] =
    Store.read(path).map {
      case Left(err)     => CliResult(err, ExitCode.Error)
      case Right(Nil)    => CliResult("no todos", ExitCode.Success)
      case Right(todos)  => CliResult(render(todos), ExitCode.Success)
    }

  private def render(todos: List[Todo]): String =
    todos
      .map(t => s"#${t.id} [${if t.done then "x" else " "}] ${t.title.value}")
      .mkString("\n")

