package todo

import cats.effect.{ExitCode, IO, IOApp}
import java.nio.file.{Path, Paths}

object Main extends IOApp:

  private val storePath: Path = Paths.get("todos.yaml")

  def run(args: List[String]): IO[ExitCode] =
    args match
      case Nil                     => greet.as(ExitCode.Success)
      case "add" :: rawTitle :: Nil => print(Commands.add(storePath, rawTitle))
      case "list" :: Nil            => print(Commands.list(storePath))
      case other                    => print(IO.pure(CliResult(s"unknown command: ${other.mkString(" ")}", ExitCode.Error)))

  /** Prints the M2 greeting and resolves to the text it printed, so a test
    * can run this very `IO` and assert on its result instead of capturing
    * real stdout.
    */
  def greet: IO[String] =
    IO.println(Greeting.message).as(Greeting.message)

  private def print(result: IO[CliResult]): IO[ExitCode] =
    result.flatMap(r => IO.println(r.output).as(r.exitCode))

